// clang-format on
float width(const char *words, float height, Face face, float tracking) {
    const Glyph *glyphs = face == Face::Italic ? italicGlyphs : regularGlyphs;
    const float scale = height / (face == Face::Italic ? italicCapHeight : regularCapHeight);
    float result = 0;
    for (const unsigned char *p = reinterpret_cast<const unsigned char *>(words); *p; ++p)
        if (*p >= 32 && *p <= 126)
            result += glyphs[*p - 32].advance * scale + (p[1] ? tracking : 0);
    return result;
}
void draw(float x, float y, const char *words, float height, Color c, Face face, float tracking) {
    const bool italic = face == Face::Italic;
    const Glyph *glyphs = italic ? italicGlyphs : regularGlyphs;
    const unsigned short *indices = italic ? italicIndices : regularIndices;
    const float scale = height / (italic ? italicCapHeight : regularCapHeight);
    glPushMatrix();
    glTranslatef(x, y, 0);
    glScalef(scale, scale, 1);
    color(c);
    glEnableClientState(GL_VERTEX_ARRAY);
    glVertexPointer(2, GL_SHORT, sizeof(Point), italic ? italicPoints : regularPoints);
    for (const unsigned char *p = reinterpret_cast<const unsigned char *>(words); *p; ++p) {
        if (*p < 32 || *p > 126)
            continue;
        const Glyph &g = glyphs[*p - 32];
        if (g.count)
            glDrawElements(GL_TRIANGLES, static_cast<GLsizei>(g.count), GL_UNSIGNED_SHORT,
                           indices + g.first);
        glTranslatef(g.advance + tracking / scale, 0, 0);
    }
    glDisableClientState(GL_VERTEX_ARRAY);
    glPopMatrix();
}
void centered(float x, float y, const char *words, float height, Color c, Face face,
              float tracking) {
    draw(x - width(words, height, face, tracking) / 2, y, words, height, c, face, tracking);
}
